def variants(points):
    out=[]
    for refl in [False,True]:
        for k in range(4):
            pts=[]
            for r,c in points:
                if refl: c=-c
                for _ in range(k): r,c=c,-r
                pts.append((r,c))
            r0=min(r for r,c in pts); c0=min(c for r,c in pts)
            pts=tuple(sorted((r-r0,c-c0) for r,c in pts))
            if pts not in out: out.append(pts)
    return out
