def match_results(g, color):
    h,w=len(g),len(g[0]); ms=[]
    for pts in variants([(r,c) for r,row in enumerate(g) for c,x in enumerate(row) if x==color]):
        mh=max(r for r,c in pts)+1; mw=max(c for r,c in pts)+1
        for i in range(h-mh+1):
            for j in range(w-mw+1):
                if all(g[i+r][j+c]==0 for r,c in pts): ms.append((i,j,pts))
    return ms
