def apply_pattern(g, marker, all_orient=True):
    h,w=len(g),len(g[0]); orig=[(r,c) for r,row in enumerate(g) for c,x in enumerate(row) if x==marker]
    shapes=variants(orig) if all_orient else [tuple(sorted((r-min(x for x,y in orig),c-min(y for x,y in orig)) for r,c in orig))]
    changed=set()
    for pts in shapes:
        mh=max(r for r,c in pts)+1; mw=max(c for r,c in pts)+1
        for i in range(h-mh+1):
            for j in range(w-mw+1):
                if all(g[i+r][j+c]==0 for r,c in pts):
                    changed.update((i+r,j+c) for r,c in pts)
    out=[row[:] for row in g]
    for r,c in changed: out[r][c]=marker
    return out,changed
